import React, { useEffect } from "react";
import { useAppContext } from "../../../contextApi/AppContext";
import { useParams } from "react-router-dom";
import { Card, Col, Container, Row, ListGroup } from "react-bootstrap";
import moment from "moment";

const SubscriptionDetail = () => {
  const { id } = useParams();
  const { getSubsCourseDetail, subsCourseDetail } = useAppContext();

  console.log(subsCourseDetail);

  useEffect(() => {
    getSubsCourseDetail(id);
    // eslint-disable-next-line
  }, [id]);

  const {
    current_plan_end,
    current_plan_start,
    subscription_history,
    product_plans,
    product_details,
    upcoming_meetings,
  } = subsCourseDetail;

  return (
    <Container className="mt-4">
      <Row>
        <Col md={4}>
          <Card className="mb-4">
            <Card.Img variant="top" src={product_details?.image} alt={""} />
          </Card>
        </Col>
        <Col md={8}>
          <Card className="mb-4">
            <Card.Body>
              <Card.Title>{product_details?.title}</Card.Title>
              <Card.Text>{product_details?.description}</Card.Text>
              <Card.Text>
                purchase Mode : {product_details?.purchase_mode}
              </Card.Text>
            </Card.Body>
            <ListGroup variant="flush">
              <ListGroup.Item>
                <strong>Current Plan:</strong> {product_plans?.plan_name}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Plan Price:</strong> ${product_plans?.plan_price}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Plan Interval:</strong> {product_plans?.plan_interval}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Plan Interval Count:</strong>{" "}
                {product_plans?.plan_interval_count}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Current Plan Start:</strong>{" "}
                {moment(current_plan_start).format("LLL")}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Current Plan End:</strong>{" "}
                {moment(current_plan_end).format("LLL")}
              </ListGroup.Item>
              <ListGroup.Item>
                <strong>Subscription History:</strong>{" "}
                {Array.isArray(subscription_history) &&
                  subscription_history.map((historyItem) => (
                    <span
                      key={historyItem._id}
                      className="d-block mb-1"
                      style={{ fontSize: "0.9rem" }}
                    >
                      <h6
                        className={`mb-0 ${
                          historyItem.payment_status === "Failed"
                            ? "text-danger"
                            : historyItem.payment_status === "Success"
                            ? "text-success"
                            : ""
                        }`}
                      >
                        {historyItem.payment_status}
                      </h6>
                      {historyItem.amount} USD - from{" "}
                      {moment(historyItem.current_plan_start).format("LL")}
                      <span>
                        {" "}
                        to {moment(historyItem.current_plan_end).format("LL")}
                      </span>
                    </span>
                  ))}
              </ListGroup.Item>
              <ListGroup.Item>
                <h6>Upcoming Meetings:</h6>
                {Array.isArray(upcoming_meetings) &&
                  upcoming_meetings?.map((meeting) => (
                    <Card key={meeting._id} className="mb-2">
                      <Card.Body>
                        <Card.Title>{meeting.meeting_agenda}</Card.Title>
                        <Card.Text>
                          <strong>Date:</strong>{" "}
                          {moment(meeting.meetingAt).format("LL")}
                          <br />
                          <strong>Duration:</strong> {meeting.duration} minutes
                          <br />
                          <strong>Time:</strong>{" "}
                          {moment(meeting.meetingAt).format("LT")}
                        </Card.Text>
                        <a
                          href={meeting.meeting_join_url}
                          className="btn btn-primary text-white"
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          Join Meeting
                        </a>
                      </Card.Body>
                    </Card>
                  ))}
              </ListGroup.Item>
            </ListGroup>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default SubscriptionDetail;
