import React, { useEffect } from "react";
import Ads from "../../../components/comon/Ads";
import { Link } from "react-router-dom";
import AccountSideBar from "../AccountSideBar";
import { useAppContext } from "../../../contextApi/AppContext";
import { Skeleton3 } from "../../../components/loading/Skeleton";
import NoData from "../../noData/NoData";

const MyOrder = () => {
  const { orderList, getMyOrderList, listLoading } = useAppContext();

  useEffect(() => {
    const fetchData = async () => {
      await getMyOrderList();
    };
    fetchData();
    // eslint-disable-next-line
  }, []);

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-6">
              <h4>My Order</h4>
            </div>
            <div className="col-md-6">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li className="active">My Order</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
            {/* sidebar start */}
            <div className="col-md-3">
              <AccountSideBar />
            </div>
            {/* sidebar end */}
            {/* right part start */}
            <div className="col-md-7">
              <div className="card border-0 mt-0">
                <div className="card-body">
                  <h2 className="text24 mb-1">My Order</h2>
                  <p className="text-muted mb-1">
                    Here you can see your Orders.
                  </p>
                  <hr className="mt0" />
                  {/* item start */}
                  {listLoading.Post ? (
                    Array.from({ length: 3 }).map((_, index) => (
                      <Skeleton3 key={index} />
                    ))
                  ) : Array.isArray(orderList) && orderList.length === 0 ? (
                    <NoData des={"Place An Order, to See your Orders Thank you!."} />
                  ) : (
                    Array.isArray(orderList) &&
                    orderList.map((item, i) => (
                      <div className="myPostItem" key={i}>
                        {item?.items.map((it, j) => (
                          <div className="card">
                            <div className="card-body">
                          <div className="row" style={{alignItems:'center'}}>
                            <div className="col-md-2">
                              <div className="imgBx">
                                <img
                                  src={it.image}
                                  className="img-fluid"
                                  alt="Dzital"
                                />
                              </div>
                            </div>
                            <div className="col-md-10">
                              <h5 className="mb-1">{it.title}</h5>
                              <p className="mb-0">Quantity : {it.quantity}</p>
                              <p className="mb-0">Total Price : {it.total_price}</p>
                            </div>
                          </div>
                          </div>
                          </div>
                        ))}
                        {/* {console.log('hgg' ,item)} */}
                      </div>
                    ))
                  )}
                  {/* item end */}
                </div>
              </div>
            </div>
            {/* right part end */}
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>
      </section>
    </>
  );
};

export default MyOrder;
