import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useAppContext } from "../../contextApi/AppContext";
import noPostar from '../../assets/no-poster.png'


const ElectronicsBanner = ({ item }) => {
  const { electronicsList, wishListAdd, wishListRemove, userData } = useAppContext();
  const [colorMap, setColorMap] = useState([]);


  const addWhishlist = (id) => {
    if (colorMap[id]) {
      wishListRemove(id);
      const filtered = { ...colorMap }
      filtered[id] = false
      setColorMap(filtered)
    } else {
      wishListAdd(id);
      setColorMap((prevColorMap) => ({
        ...prevColorMap,
        [id]: !prevColorMap[id],
      }));
    }
  };

  useEffect(() => {
    if (electronicsList && Array.isArray(electronicsList)) {
      let check = {}
      electronicsList.forEach((list) => {
        check[list.product_id] = list.isWishlist
      })
      setColorMap(check)
    }
  }, [electronicsList])

  return (
    <>
      <section className="bg-light">
        <article className="container pt-4 pb-4">
          <div className="d-flex justify-content-between align-items-center">
            <h4 className="m-0">{item.title}</h4>
            <Link className="text text-decoration-none " to={`/${item.slug}?category_id=${item._id}`} onMouseEnter={(e) => (e.target.style.color = "var(--theme-color)")} onMouseLeave={(e) => e.target.style.color = "black"}>
              View All
            </Link>
          </div>
          <aside className="row pt-2 ">
            {/* item start */}
            {Array.isArray(electronicsList) && electronicsList.slice(0, 4).map((item) => (
              <div className="col-md-3 col-12 proBx" key={item._id}>
                <div className="card mb-3">
                  <div className="imgBx  ">
                    <Link to={`/Electronics-detail/${item._id}`}>
                      <img
                        src={item.photo || noPostar}
                        className="card-img-top allImg "
                        alt=""
                      />
                    </Link>
                    {item.userId === userData._id ? '' : (
                      <div
                        className="iconWish"
                        onClick={() => addWhishlist(item.product_id)}
                      >
                        <i
                          className={
                            (colorMap[item.product_id])
                              ? "fa fa-heart text-danger"
                              : "fa fa-heart-o"
                          }
                        />
                      </div>
                    )}
                  </div>
                  <div className="card-body">
                    <h5 className="card-title">
                      <Link to={`/Electronics-detail/${item._id}`}>
                        {item.title}
                      </Link>
                    </h5>
                    <p style={{ overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical" }}>{item.description}</p>
                  </div>
                </div>
              </div>
            ))
            }
          </aside>
        </article>
      </section>
    </>
  )
}

export default ElectronicsBanner