import React, {useState} from 'react'
import { Link } from 'react-router-dom'
import { useAppContext } from '../../contextApi/AppContext'

const RealstateProduct = ({ item }) => {
  const { wishListAdd, wishListRemove, userData } = useAppContext();
  const [color, setColor] = useState(item.isWishlist);

  const handleWhishlist = (id) => {
    if (color) {
      wishListRemove(id);
    } else {
      wishListAdd(id);
    }
    setColor(!color);
  };

  return (
    <>
      <div className="card mb-3 realestateItem">
        <div className="row g-0" key={item._id}>
          <div className="col-md-4">
            <Link to={`/realstate-detail/${item._id}`}>
              <img
                src={item.photo}
                className="img-fluid rounded-start allImg"
                style={{ height: '220px' }}
                alt="..."
                width={400}
              />
            </Link>
          </div>
          <div className="col-md-8">
            <div className="card-body">
              <h5 className="card-title">
                <Link to={`/realstate-detail/${item._id}`}>
                  {item.title}
                </Link>
              </h5>
              <div className="row">
              {userData._id === item.userId ? '' : (
                  <div className="iconWish" onClick={() => handleWhishlist(item.product_id)}>
                    <i className={`fa ${color ? 'fa-heart text-danger' : 'fa-heart-o'}`} />
                  </div>
              )}
              </div>
              <p style={{ overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical" }}>{item.description}</p>
              <Link className="btn btnTheme" style={{ background: "var(--theme-color)" }} to={`/realstate-detail/${item._id}`}>
                View Property &gt;&gt;
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

export default RealstateProduct