import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const NotificationModal = () => {
    const [isOpen, setIsOpen] = useState(false);

    const toggleDropdown = () => {
        setIsOpen(!isOpen);
    };

    return (
        <li className="dropdown" >
            <Link
                className="me-3 dropdown-toggle hidden-arrow"
                id="navbarDropdownMenuLink"
                role="button"
                onClick={toggleDropdown}
                aria-expanded={isOpen ? "true" : "false"}
            >
                <i className="fas fa-bell"></i>
                <span className="badgeBx badge rounded-pill bg-danger">1</span>
            </Link>
            <div style={{minWidth:'350px'}} className={`notification-list-content ${isOpen ? 'show' : ''}`}>
                {/* item start */}
                <div className="notification-list-item mb-2">
                    <div className="notification-list-img">
                        <img src="https://i.imgur.com/zYxDCQT.jpg" alt="user" />
                    </div>
                    <div className="notification-list-detail">
                        <p className='mb-0'><b>John Doe</b> reacted to your post</p>
                        <p className='mb-0'><small>Lorem Ipsum is simply dummy text of..</small></p>
                        <p className='mb-0 text-secondary'><small><i class="fas fa-calendar-alt"></i> 17 Jun 2024</small></p>
                    </div>
                </div>
                {/* item end */}
                <hr className='mb-2' />
                {/* item start */}
                <div className="notification-list-item">
                    <div className="notification-list-img">
                        <img src="https://i.imgur.com/zYxDCQT.jpg" alt="user" />
                    </div>
                    <div className="notification-list-detail">
                        <p className='mb-0'><b>John Doe</b> reacted to your post</p>
                        <p className='mb-0'><small>Lorem Ipsum is simply dummy text of..</small></p>
                        <p className='mb-0 text-secondary'><small><i class="fas fa-calendar-alt"></i> 17 Jun 2024</small></p>
                    </div>
                </div>
                {/* item end */}
                <hr className='mb-2' />
                {/* item start */}
                <div className="notification-list-item">
                    <div className="notification-list-img">
                        <img src="https://i.imgur.com/zYxDCQT.jpg" alt="user" />
                    </div>
                    <div className="notification-list-detail">
                        <p className='mb-0'><b>John Doe</b> reacted to your post</p>
                        <p className='mb-0'><small>Lorem Ipsum is simply dummy text of..</small></p>
                        <p className='mb-0 text-secondary'><small><i class="fas fa-calendar-alt"></i> 17 Jun 2024</small></p>
                    </div>
                </div>
                {/* item end */}
            </div>
        </li>
    );
}

export default NotificationModal;
